import { playerProduction } from './dashboardData';
import { positionFor, positionStyles } from './positionStyles';

export const contributionColors = ['#95ddbf', '#89b8ff', '#c1a1f7', '#f1cc7d', '#eea9c4', '#79d3df', '#f4ad7b', '#b9d77e', '#a0a8f4', '#e8a3a3', '#78c2ab', '#d3c0a5'];

// A pie cannot represent negative areas. Keep signed points in the legend and
// net total, but use positive player totals as the denominator when necessary.
export function contributionTotals(players) {
  const net = players.reduce((sum, player) => sum + player.pointHundredths, 0);
  const positive = players.reduce((sum, player) => sum + Math.max(0, player.pointHundredths), 0);
  return { net: net / 100, positive: positive / 100, hasNegative: players.some((player) => player.pointHundredths < 0),
    share: (player) => positive > 0 ? Math.max(0, player?.pointHundredths ?? 0) / positive : null };
}

export function productionByPosition(players) {
  return Object.keys(positionStyles).map((position) => {
    const contributors = players.filter((player) => positionFor(player).label === position);
    return { position, players: contributors, ...contributionTotals(contributors) };
  }).filter((group) => group.players.length);
}

export function playerContribution(player, team, matchups, scope = 'position') {
  const players = playerProduction(team, matchups);
  const contributor = players.find((candidate) => player.yahoo_player_key
    ? candidate.yahoo_player_key === player.yahoo_player_key : candidate.name === player.name);
  const position = positionFor(contributor ?? player).label;
  const pool = scope === 'team' ? players : players.filter((candidate) => positionFor(candidate).label === position);
  const totals = contributionTotals(pool);
  return { ...totals, position, points: contributor?.points ?? 0, starts: contributor?.starts ?? 0,
    fraction: totals.share(contributor) };
}
