import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { Modal } from 'react-bootstrap';
import { formatPoints, teamHref } from './dashboardData';
import { getPlayerHistory } from './playerHistoryData';
import PlayerRosValue from './PlayerRosValue';
import PlayerContributionShares from './PlayerContributionShares';

const PlayerHistoryContext = createContext(null);

export function PlayerName({ player, children }) {
  const context = useContext(PlayerHistoryContext);
  if (!context) return <>{children ?? player.name}</>;
  return <button type="button" className="player-name-trigger" aria-haspopup="dialog" title={`View league history for ${player.name}`} onClick={(event) => {
    event.stopPropagation();
    context.openPlayer(player, player.historyData);
  }}>{children ?? player.name}</button>;
}

export function PlayerHistoryProvider({ data, children }) {
  const [selection, setSelection] = useState(null);
  const [show, setShow] = useState(false);
  const openPlayer = useCallback((player, playerData = data) => { setSelection({ player, data, playerData }); setShow(true); }, [data]);
  const context = useMemo(() => ({ openPlayer }), [openPlayer]);
  useEffect(() => {
    if (selection && selection.data !== data) { setShow(false); setSelection(null); }
  }, [data, selection]);
  return <PlayerHistoryContext.Provider value={context}>
    {children}
    {selection && selection.data === data && data && <PlayerHistoryModal player={selection.player} data={selection.playerData} show={show} onHide={() => setShow(false)} onExited={() => setSelection(null)} />}
  </PlayerHistoryContext.Provider>;
}

function RosterLink({ team, onHide }) {
  return team.team_id != null && !team.historical ? <a className="player-roster-link" href={teamHref(team)} onClick={onHide}>{team.logo_image && <img src={team.logo_image} alt="" />}{team.name}</a> : <span>{team.name}</span>;
}

function RoleBadge({ entry }) {
  const kind = entry.role === 'Started' ? 'started' : entry.role === 'Bench' ? 'bench' : 'inactive';
  return <span className={`player-role role-${kind}`}>{entry.role}{entry.role === 'Started' && entry.position ? ` · ${entry.position}` : ''}</span>;
}

function PlayerHistoryModal({ player, data, show, onHide, onExited }) {
  const history = useMemo(() => getPlayerHistory(player, data), [player, data]);
  const lastWeek = history.appearances[history.appearances.length - 1]?.week ?? 1;
  const [selectedWeek, setSelectedWeek] = useState(lastWeek);
  useEffect(() => setSelectedWeek(lastWeek), [player.yahoo_player_key, player.name, lastWeek]);
  const selected = history.weeks.find((week) => week.week === selectedWeek);
  const maximum = Math.max(0, ...history.weeks.map((week) => week.points ?? 0));
  const minimum = Math.min(0, ...history.weeks.map((week) => week.points ?? 0));
  const range = maximum - minimum || 1;
  const info = history.player;
  return <Modal show={show} onHide={onHide} onExited={onExited} size="lg" centered scrollable fullscreen="md-down" aria-labelledby="player-history-title" className="player-history-modal">
    <Modal.Header closeButton><div className="player-history-heading">
      {info.headshot_image && <img src={info.headshot_image} alt="" />}
      <div><p className="eyebrow">{data.metadata?.season ? `${data.metadata.season} · ` : ''}League player history</p><Modal.Title as="h2" id="player-history-title">{info.name}</Modal.Title><p className="muted">{info.team} · {info.positions?.join(', ')}</p></div>
    </div></Modal.Header>
    <Modal.Body>
      <PlayerRosValue player={info} data={data} />
      {history.appearances.length ? <>
        <dl className="player-history-stats">
          <div><dt>Rostered points</dt><dd>{formatPoints(history.recordedPoints)}</dd></div>
          <div><dt>Weeks started</dt><dd>{history.weeksStarted}</dd></div>
          <div><dt>Starter points</dt><dd>{formatPoints(history.starterPoints)}</dd></div>
          <div><dt>League rosters</dt><dd>{history.rosters.length}</dd></div>
          {history.weeks.some((week) => week.supplemental) && <><div><dt>Off-roster / additional points</dt><dd>{formatPoints(history.supplementalPoints)}</dd></div><div><dt>All recorded points</dt><dd>{formatPoints(history.allRecordedPoints)}</dd></div></>}
        </dl>
        <PlayerContributionShares player={info} data={data} rosters={history.rosters} />
        <div className="player-chart-heading"><h3>Week by week</h3><div className="player-usage-legend"><span><i className="usage-started" />Started</span><span><i className="usage-benched" />Bench / IR</span>{history.weeks.some((week) => week.supplemental) && <span><i className="usage-unrostered" />Off-roster / unknown roster</span>}</div></div>
        <p className="muted player-chart-help">Bar color shows the league roster. Select a week for details. Includes postseason games.</p>
        <div className="player-weeks-scroll" role="region" aria-label="Weekly player scoring chart" tabIndex="0">
          <div className="player-weeks-chart">{history.weeks.map((week) => {
            const points = week.points;
            const roles = [...new Set(week.entries.map((entry) => entry.role))].join(' / ');
            const label = `Week ${week.week}: ${week.entries.length ? `${points == null ? 'Score unavailable' : `${formatPoints(points)} points`}, ${roles}, ${week.entries.map((entry) => entry.team.name).join(' / ')}` : week.supplemental ? `${formatPoints(points)} points, ${week.unrostered ? 'Unrostered' : 'No roster record'}` : 'No roster record'}`;
            const color = week.entries.length === 1 ? history.colorFor(week.entries[0].team) : '#acbdc9';
            return <button key={week.week} className={`player-week${week.entries.length || week.supplemental ? '' : ' player-week-missing'}${week.supplemental ? ' player-week-unrostered' : ''}`} aria-label={label} aria-pressed={selectedWeek === week.week} title={label} onClick={() => setSelectedWeek(week.week)} style={{ '--roster-color': color }}>
              <span className="player-week-score" aria-hidden="true">{points == null ? '—' : formatPoints(points)}</span>
              <span className="player-week-plot" aria-hidden="true"><span className="player-week-zero" style={{ bottom: `${-minimum / range * 100}%` }} />
                {points != null && <span className={`player-week-bar${week.supplemental ? ' player-week-supplemental' : week.started ? '' : ' player-week-benched'}`} style={{
                  bottom: `${(Math.min(0, points) - minimum) / range * 100}%`, height: points === 0 ? '2px' : `${Math.abs(points) / range * 100}%`,
                }} />}
                {!week.entries.length && !week.supplemental && <span className="player-week-gap">—</span>}
              </span>
              <span className="player-week-label" aria-hidden="true">W{week.week}</span>
            </button>;
          })}</div>
        </div>
        <ul className="player-roster-legend" aria-label="League roster colors">{history.rosters.map((team) => <li key={team.team_id ?? team.name}><i style={{ background: history.colorFor(team) }} /><RosterLink team={team} onHide={onHide} /></li>)}</ul>
        {selected && <section className="player-selected-week" aria-labelledby="selected-player-week-title">
          <div className="section-heading"><h3 id="selected-player-week-title">Week {selected.week}</h3><strong>{selected.points == null ? selected.scoreConflict ? 'Scores vary' : '—' : `${formatPoints(selected.points)} pts`}</strong></div>
          {selected.entries.length ? <ul>{selected.entries.map((entry) => <li key={entry.team.team_id ?? entry.team.name}><RosterLink team={entry.team} onHide={onHide} /><RoleBadge entry={entry} />{entry.type !== 'regular' && <span className="muted">{entry.type === 'consolation' ? 'Consolation' : 'Playoff'}</span>}{selected.scoreConflict && <strong>{entry.points == null ? '—' : formatPoints(entry.points)} pts</strong>}</li>)}</ul> : <p className="muted">{selected.supplemental ? `${selected.unrostered ? 'Unrostered' : 'No roster record'} · These points are not credited to any fantasy team.` : 'No roster record for this week.'}</p>}
        </section>}
        <details className="player-weekly-log"><summary>Full weekly log</summary><div className="table-scroll"><table>
          <caption className="visually-hidden">Weekly league rosters, lineup use, and player scores</caption>
          <thead><tr><th scope="col">Week</th><th scope="col">League roster</th><th scope="col">Lineup</th><th scope="col">Points</th></tr></thead>
          <tbody>{history.weeks.flatMap((week) => week.entries.length ? week.entries.map((entry) => <tr key={`${week.week}-${entry.team.team_id ?? entry.team.name}`}><th scope="row">{week.week}</th><td><RosterLink team={entry.team} onHide={onHide} /></td><td><RoleBadge entry={entry} /></td><td>{entry.points == null ? '—' : formatPoints(entry.points)}</td></tr>) : [<tr key={week.week}><th scope="row">{week.week}</th>{week.supplemental ? <><td>{week.unrostered ? 'Unrostered' : 'No roster record'}</td><td>—</td><td>{formatPoints(week.points)}</td></> : <td colSpan="3" className="muted">No roster record</td>}</tr>])}</tbody>
        </table></div></details>
        <p className="muted player-history-note">Rostered and starter totals cover league rosters only. Additional weekly scores appear in neutral bars and never count toward fantasy-team production. Unfetched gaps remain unknown; they can include unrostered weeks, playoff byes, or unavailable roster data. Roster changes show weekly ownership, with no exact trade dates implied.</p>
      </> : <p className="muted">No weekly roster history is available for this player yet.</p>}
      {history.keeperOptions.length > 0 && <section className="player-keeper-options" aria-labelledby="player-keeper-title"><h3 id="player-keeper-title">Keeper eligibility{data.metadata?.keeper_roster_week ? ` · Week ${data.metadata.keeper_roster_week}` : ''}</h3>{history.keeperOptions.map((keeper) => <div key={keeper.team.team_id ?? keeper.team.name}><RosterLink team={keeper.team} onHide={onHide} /><span>Round <strong>{keeper.round}</strong></span><span className={`tier-badge tier-${keeper.tier}`}>{keeper.tier}</span><p className="muted">{keeper.draft_status}</p></div>)}</section>}
    </Modal.Body>
    <Modal.Footer><button type="button" className="retry-button" onClick={onHide}>Close player history</button></Modal.Footer>
  </Modal>;
}
