import React from 'react';
import { formatPoints, teamHref } from './dashboardData';

const matchesTeam = (entry, team) => entry && (
  entry.team_id != null && team.team_id != null
    ? String(entry.team_id) === String(team.team_id) : entry.name === team.name
);

export function teamResults(team, matchups, teams = []) {
  return matchups.flatMap((matchup) => {
    const side = matchesTeam(matchup.team0, team) ? 'team0' : matchesTeam(matchup.team1, team) ? 'team1' : null;
    if (!side) return [];
    const entry = matchup[side];
    const opponent = matchup[side === 'team0' ? 'team1' : 'team0'];
    if (!opponent) return [];
    const score = entry.points == null ? null : Number(entry.points);
    const against = opponent.points == null ? null : Number(opponent.points);
    const scored = score != null && against != null && Number.isFinite(score) && Number.isFinite(against);
    const difference = scored ? Math.round(score * 100) - Math.round(against * 100) : null;
    return [{
      week: matchup.week, type: matchup.matchup_type ?? 'regular',
      opponent: teams.find((candidate) => matchesTeam(opponent, candidate)) ?? opponent,
      score: Number.isFinite(score) ? score : null,
      against: Number.isFinite(against) ? against : null,
      result: scored ? difference > 0 ? 'W' : difference < 0 ? 'L' : 'T' : null,
    }];
  }).sort((a, b) => a.week - b.week);
}

export default function TeamResults({ team, data }) {
  const results = teamResults(team, data.matchups, data.teams);
  const outcomes = { W: 'Win', L: 'Loss', T: 'Tie' };
  return <section className="panel" aria-labelledby="team-results-title">
    <div className="section-heading"><div><p className="eyebrow">How the season unfolded</p><h2 id="team-results-title">Weekly results</h2></div><span className="count-badge">{results.length} {results.length === 1 ? 'game' : 'games'}</span></div>
    {results.length ? <div className="table-scroll" role="region" aria-label="Scrollable weekly results" tabIndex="0">
      <table className="team-results-table">
        <caption className="visually-hidden">{team.name} weekly opponents, scores, and results. Scores are shown from your team’s perspective.</caption>
        <thead><tr><th scope="col">Week</th><th scope="col">Opponent</th><th scope="col">Your score</th><th scope="col">Opponent score</th><th scope="col">Result</th></tr></thead>
        <tbody>{results.map((game) => <tr key={`${game.week}-${game.opponent.team_id ?? game.opponent.name}-${game.type}`}>
          <th scope="row">Week {game.week}{game.type !== 'regular' && <span className="result-game-type">{game.type === 'consolation' ? 'Consolation' : 'Playoff'}</span>}</th>
          <td>{game.opponent.team_id != null ? <a className="team-link" href={teamHref(game.opponent)}>{game.opponent.logo_image && <img src={game.opponent.logo_image} alt="" loading="lazy" />}{game.opponent.name}</a> : game.opponent.name}</td>
          <td>{game.score == null ? '—' : formatPoints(game.score)}</td>
          <td>{game.against == null ? '—' : formatPoints(game.against)}</td>
          <td>{game.result ? <span className={`weekly-result result-${game.result.toLowerCase()}`} aria-label={outcomes[game.result]} title={outcomes[game.result]}>{game.result}</span> : '—'}</td>
        </tr>)}</tbody>
      </table>
    </div> : <p className="muted">No weekly results yet.</p>}
  </section>;
}
