import { baselineRanks, draftProduction } from './draftProductionData';
import { normalizeData } from './dashboardData';

export const eliteWeeklyRanks = { QB: 6, RB: 12, WR: 12, TE: 6 };

// Weekly thresholds use the same positional pool as the season-value analysis.
export function weeklyDraftProduction(data, level = 'starter') {
  if (data.historical_seasons) {
    const seasons = Object.fromEntries(data.historical_seasons.map((archive) => {
      const normalized = normalizeData(archive);
      normalized.teams = normalized.teams.map((team) => ({ ...team, historical: true }));
      return [normalized.metadata.season, weeklyDraftProduction(normalized, level)];
    }).filter(([, model]) => model));
    const base = draftProduction(data, true, true);
    if (!base) return null;
    return { ...base, seasons, seasonWeeks: Math.max(...Object.values(seasons).map((model) => model.seasonWeeks)),
      players: Object.entries(seasons).flatMap(([season, model]) => model.players.map((player) => ({
        ...player, season: Number(season), historyData: model.historyData,
        x: base.exactPicks ? player.x : player.draft?.round ?? null,
      }))) };
  }
  const base = draftProduction(data, true, true);
  if (!base) return null;
  const ranks = level === 'elite' ? eliteWeeklyRanks : Object.fromEntries(Object.entries(baselineRanks).map(([position, rank]) => [position, rank - 1]));
  const eligible = base.players.filter((p) => ranks[p.position]);
  const scores = new Map(eligible.map((p) => [p.key, new Map()]));
  const matchups = (data.matchups ?? []).filter((m) => !m.matchup_type || m.matchup_type === 'regular');
  const weeks = [...new Set(matchups.map((m) => Number(m.week)))].sort((a, b) => a - b);
  const supplemental = Number(data.player_week_points?.season) === Number(data.metadata?.season) ? data.player_week_points.points : {};
  for (const p of eligible) {
    for (const week of weeks) {
      const value = supplemental?.[p.key]?.[week];
      if (value != null && Number.isFinite(Number(value))) scores.get(p.key).set(week, Math.round(Number(value) * 100));
    }
  }
  // Recorded roster scores take precedence over supplemental scores.
  for (const m of matchups) for (const side of ['team0', 'team1']) for (const p of m[side]?.roster ?? []) {
    if (scores.has(p.yahoo_player_key) && p.points != null && Number.isFinite(Number(p.points))) {
      scores.get(p.yahoo_player_key).set(Number(m.week), Math.round(Number(p.points) * 100));
    }
  }
  const thresholds = Object.fromEntries(Object.entries(ranks).map(([position, rank]) => [position,
    new Map(weeks.map((week) => {
      const ranked = eligible.filter((p) => p.position === position).map((p) => scores.get(p.key).get(week))
        .filter((value) => value !== undefined).sort((a, b) => b - a);
      return [week, ranked[rank - 1] ?? null];
    })),
  ]));
  return { ...base, historyData: data, seasonWeeks: weeks.length,
    players: eligible.map((p) => {
      const qualifyingWeeks = weeks.filter((week) => {
        const cutoff = thresholds[p.position].get(week), value = scores.get(p.key).get(week);
        return cutoff != null && value > 0 && value >= cutoff;
      });
      return { ...p, points: qualifyingWeeks.length, qualifyingWeeks,
        seasonWeeks: weeks.length, observedWeeks: scores.get(p.key).size,
        unavailableWeeks: weeks.filter((week) => thresholds[p.position].get(week) == null).length,
        weekPercentage: weeks.length ? qualifyingWeeks.length / weeks.length * 100 : 0 };
    }) };
}
