import React, { useEffect, useMemo, useState } from 'react';
import DraftProduction from './DraftProduction';
import { normalizeData } from './dashboardData';

export default function DraftProductionPage({ data }) {
  const [view, setView] = useState('current');
  const [history, setHistory] = useState(null);
  const [error, setError] = useState(null);
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    if (view === 'current' || history) return undefined;
    const controller = new AbortController();
    setError(null);
    fetch(`${process.env.PUBLIC_URL}/league_history.json`, { signal: controller.signal })
      .then((response) => {
        if (!response.ok) throw new Error(`Could not load historical data (HTTP ${response.status}).`);
        return response.json();
      }).then((json) => {
        if (json.schema_version !== 1 || !Array.isArray(json.seasons) || !json.seasons.length) throw new Error('Historical data has an unsupported format.');
        const seasons = new Set();
        for (const season of json.seasons) {
          normalizeData(season);
          if (!season.metadata?.season || seasons.has(season.metadata.season)) throw new Error('Historical data has missing or duplicate seasons.');
          seasons.add(season.metadata.season);
        }
        if (!controller.signal.aborted) setHistory(json.seasons);
      }).catch((reason) => { if (!controller.signal.aborted) setError(reason.message); });
    return () => controller.abort();
  }, [view, history, attempt]);
  const combined = useMemo(() => history ? { historical_seasons: history } : null, [history]);
  return <>
    <div className="contribution-toggle draft-history-toggle" role="group" aria-label="Draft analysis seasons">
      <button type="button" aria-pressed={view === 'current'} onClick={() => setView('current')}>Current season</button>
      <button type="button" aria-pressed={view === 'history'} onClick={() => setView('history')}>2024–2025 combined</button>
    </div>
    {view === 'current' ? <DraftProduction key="current" data={data} /> : error ? <section className="panel" role="alert"><p>{error}</p><button type="button" className="retry-button" onClick={() => setAttempt(attempt + 1)}>Retry historical data</button></section>
      : !combined ? <p className="empty-state" role="status">Loading historical draft production…</p> : <DraftProduction key="history" data={combined} />}
  </>;
}
