export const previewChoices = [
  { id: 'current', label: 'Current league data' },
  { id: '2025w12', label: '2025 · Week 12' },
  { id: '2025w17', label: '2025 · Week 17' },
];

export async function loadPreviewData(id) {
  // Keep historical data out of published builds. These lazy imports are only
  // reachable in the local development server.
  if (process.env.NODE_ENV === 'development') {
    if (id === '2025w12') return (await import('./previews/league_data_2025w12.json')).default;
    if (id === '2025w17') return (await import('./previews/league_data_2025w17.json')).default;
  }
  throw new Error('This historical preview is unavailable.');
}
