import React, { useMemo, useState } from 'react';
import { formatPoints } from './dashboardData';
import { playerContribution } from './contributionData';
import { positionFor } from './positionStyles';
import ContributionPie from './ContributionPie';

export default function PlayerContributionShares({ player, data, rosters }) {
  const [scope, setScope] = useState('position');
  const contributions = useMemo(() => rosters.map((team) => ({ team, ...playerContribution(player, team, data.matchups, scope) })), [player, rosters, data.matchups, scope]);
  if (!rosters.length) return null;
  return <section className="player-contribution-section" aria-labelledby="player-contribution-title">
    <div className="section-heading"><h3 id="player-contribution-title">Share of production</h3>
      <div className="contribution-toggle" role="group" aria-label="Production share comparison">{[['position', 'By position'], ['team', 'Whole team']].map(([value, label]) => <button type="button" key={value} aria-pressed={scope === value} onClick={() => setScope(value)}>{label}</button>)}</div>
    </div>
    <p className="muted contribution-note">Regular-season starter points credited to each fantasy team, compared with that team’s {scope === 'position' ? 'full-season production at the same football position' : 'full-season production across all positions'}. Bench, IR, and postseason points are excluded.</p>
    <div className="contribution-grid">{contributions.map((item) => {
      const percent = item.fraction == null ? '—' : `${(item.fraction * 100).toFixed(1)}%`;
      const comparison = scope === 'position' ? `${item.position} production` : 'team production';
      const positivePoints = Math.max(0, item.points);
      return <article className="player-contribution-card" key={item.team.team_id ?? item.team.name} aria-label={`${item.team.name} production share`}>
        <div className="contribution-team">{item.team.logo_image && <img src={item.team.logo_image} alt="" />}<h4>{item.team.name}</h4></div>
        <div className="player-contribution-layout">
          <ContributionPie label={`${player.name}: ${percent} of ${item.team.name} ${comparison}${item.hasNegative ? ', using positive player totals' : ''}`} segments={[
            { key: 'player', name: player.name, points: positivePoints, color: positionFor(player).color },
            { key: 'others', name: 'Other players', points: Math.max(0, item.positive - positivePoints), color: '#485966' },
          ]} />
          <div><strong className="player-contribution-percent">{percent}</strong><span className="muted">of {comparison}</span><p>{formatPoints(item.points)} / {formatPoints(item.net)} net pts</p><span className="muted">{item.starts} {item.starts === 1 ? 'start' : 'starts'}</span></div>
        </div>
        {item.hasNegative && <p className="muted contribution-note">Slice and percentage use positive player totals; points shown are net totals.</p>}
        {item.fraction == null && <p className="muted contribution-note">No positive starter points in this comparison yet.</p>}
        <p className="muted contribution-note"><i className="contribution-key" style={{ background: positionFor(player).color }} />{player.name}<i className="contribution-key contribution-others" />Other players</p>
      </article>;
    })}</div>
  </section>;
}
