const rosterPalette = ['#95ddbf', '#89b8ff', '#c1a1f7', '#f1cc7d', '#eea9c4', '#79d3df', '#f4ad7b', '#b9d77e', '#a0a8f4', '#e8a3a3', '#78c2ab', '#d3c0a5'];
const identity = (team) => String(team.team_key ?? team.team_id ?? team.name);
const matches = (candidate, player) => player.yahoo_player_key
  ? candidate.yahoo_player_key === player.yahoo_player_key : candidate.name === player.name;
export const lineupRole = (position) => !position ? 'Unknown' : position === 'BN' ? 'Bench'
  : ['IR', 'IR+', 'IL', 'IL+', 'NA'].includes(position) ? position : 'Started';

export function getPlayerHistory(player, data) {
  const teams = Array.isArray(data.teams) ? data.teams
    : Object.entries(data.teams ?? {}).map(([name, team]) => ({ ...team, name }));
  const findTeam = (weekly) => teams.find((team) => team.team_id != null && weekly.team_id != null
    ? String(team.team_id) === String(weekly.team_id) : team.name === weekly.name) ?? weekly;
  const records = new Map();
  for (const matchup of data.matchups ?? []) {
    const week = Number(matchup.week);
    if (!Number.isInteger(week) || week < 1) continue;
    for (const side of ['team0', 'team1']) {
      const weekly = matchup[side];
      if (!weekly) continue;
      const entry = (weekly.roster ?? []).find((candidate) => matches(candidate, player));
      if (!entry) continue;
      const team = findTeam(weekly);
      const points = entry.points == null ? null : Number(entry.points);
      records.set(`${week}:${identity(team)}`, {
        week, team, player: entry, type: matchup.matchup_type ?? 'regular',
        points: Number.isFinite(points) ? Math.round(points * 100) / 100 : null,
        position: entry.selected_position, role: lineupRole(entry.selected_position),
      });
    }
  }
  const appearances = [...records.values()].sort((a, b) => a.week - b.week || a.team.name.localeCompare(b.team.name));
  const supplemental = Number(data.player_week_points?.season) === Number(data.metadata?.season)
    ? data.player_week_points?.points?.[player.yahoo_player_key] ?? {} : {};
  const latestWeek = Math.max(Number(data.metadata?.latest_completed_week ?? data.weeks) || 0,
    ...((data.matchups ?? []).map((matchup) => Number(matchup.week) || 0)));
  const weeks = Array.from({ length: latestWeek }, (_, index) => {
    const week = index + 1;
    const entries = appearances.filter((appearance) => appearance.week === week);
    const scores = [...new Set(entries.filter((entry) => entry.points != null).map((entry) => entry.points))];
    const extra = supplemental[String(week)];
    const hasSupplement = !entries.length && extra != null && Number.isFinite(Number(extra));
    const coveredTeams = new Set((data.matchups ?? []).filter((matchup) => Number(matchup.week) === week && (!matchup.matchup_type || matchup.matchup_type === 'regular'))
      .flatMap((matchup) => ['team0', 'team1'].filter((side) => matchup[side]).map((side) => identity(findTeam(matchup[side])))));
    return {
      week, entries, points: scores.length === 1 ? scores[0] : hasSupplement ? Number(extra) : null,
      supplemental: hasSupplement, unrostered: hasSupplement && teams.length > 0 && teams.every((team) => coveredTeams.has(identity(team))),
      scoreConflict: scores.length > 1, started: entries.some((entry) => entry.role === 'Started'),
    };
  });
  const leagueOrder = teams.map(identity).sort();
  const rosters = [...new Map(appearances.map((entry) => [identity(entry.team), entry.team])).values()];
  const colors = Object.fromEntries(rosters.map((team, index) => {
    const leagueIndex = leagueOrder.indexOf(identity(team));
    return [identity(team), rosterPalette[(leagueIndex < 0 ? index : leagueIndex) % rosterPalette.length]];
  }));
  const scored = weeks.filter((week) => week.points != null);
  return {
    player: appearances[appearances.length - 1]?.player ?? player,
    appearances, weeks, rosters,
    colorFor: (team) => colors[identity(team)] ?? '#acbdc9',
    recordedPoints: scored.filter((week) => week.entries.length).reduce((sum, week) => sum + Math.round(week.points * 100), 0) / 100,
    allRecordedPoints: scored.reduce((sum, week) => sum + Math.round(week.points * 100), 0) / 100,
    supplementalPoints: scored.filter((week) => week.supplemental).reduce((sum, week) => sum + Math.round(week.points * 100), 0) / 100,
    starterPoints: scored.filter((week) => week.started).reduce((sum, week) => sum + Math.round(week.points * 100), 0) / 100,
    weeksStarted: weeks.filter((week) => week.started).length,
    keeperOptions: teams.flatMap((team) => (team.eligible_keepers ?? [])
      .filter((keeper) => matches(keeper.player, player)).map((keeper) => ({ ...keeper, team }))),
  };
}
