import { PlayerName } from './PlayerHistoryDialog';
import { Card, Row, Col } from 'react-bootstrap';

function RosterTable({ team }) {
  const positionOrder = ["QB", "WR", "RB", "TE", "W/R/T", "K", "DEF", "BN", "IR"];

  const sortedRoster = [...team.roster].sort((a, b) => {
    return positionOrder.indexOf(a.selected_position) - positionOrder.indexOf(b.selected_position);
  });

  const getOptimalStartBorder = (player) => {
    if (player.selected_position === "BN" || player.selected_position === "IR") {
      return player.optimal_position !== "BN" ? "primary" : "light";
    }
    return player.optimal_position === "BN" ? "danger" : "light";
  };

  const getStarterBench = (player) => {
    return (player.selected_position === "BN" || player.selected_position === "IR") ? "dark" :"light";
  }


  return (
    <div className="team-roster">
      <h4 className="text-center mb-3">Roster</h4>
      <Row xs={1} className="g-3">
        {sortedRoster.map((player, index) => (
          <Col key={index}>
            <Card bg={getStarterBench(player)} text={getStarterBench(player) === "light" ? "dark" : "white"} border={getOptimalStartBorder(player)} style={{borderWidth: "5px" }}>
              <Card.Body className="d-flex align-items-center justify-content-between">
                {/* Selected Position */}
                <div style={{ minWidth: "50px" }}>
                  <h5 className="mb-0" style={{ fontSize: '1.2rem', fontWeight: 'bold' }}>{player.selected_position}</h5>
                </div>
                
                {/* Player Info with Aligned Image */}
                <div className="d-flex align-items-center" style={{ paddingLeft: '5px', flexGrow: 1 }}>
                  <img src={player.headshot_image} alt={player.name} width="40" className="rounded-circle me-3" />
                  <div>
                    <Card.Text className="mb-0">
                      <PlayerName player={player} /> <small>({player.team} - {player.positions.join(", ")})</small>
                    </Card.Text>
                  </div>
                </div>
                
                {/* Points */}
                <div>
                  <h5 className="mb-0" style={{ fontSize: '1.5rem', fontWeight: 'bold' }}>{player.points}</h5>
                </div>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </div>
  );
}

export default RosterTable;