import { PlayerName } from './PlayerHistoryDialog';
import React, { useState } from 'react';
import { teamHref } from './dashboardData';
import { KeeperStatus } from './TeamPage';
import KeeperPickupCandidates from './KeeperPickupCandidates';

export function filterKeeperTeams(teams, filters) {
  const query = filters.search.trim().toLowerCase();
  return [...teams]
    .filter((team) => !filters.teamIds.length || filters.teamIds.includes(String(team.team_id)))
    .sort((a, b) => a.name.localeCompare(b.name))
    .map((team) => ({ ...team, eligible_keepers: team.eligible_keepers.filter((keeper) => {
      const player = keeper.player;
      return (!query || `${player.name} ${player.team} ${team.name}`.toLowerCase().includes(query))
        && (!filters.position || player.positions.includes(filters.position))
        && (!filters.tier || keeper.tier === filters.tier)
        && keeper.round >= filters.minRound && keeper.round <= filters.maxRound;
    }).sort((a, b) => filters.sort === 'name'
      ? a.player.name.localeCompare(b.player.name)
      : a.round - b.round || a.player.name.localeCompare(b.player.name)) }));
}

export default function KeeperComparison({ data }) {
  const allKeepers = data.teams.flatMap((team) => team.eligible_keepers);
  const maxRound = Math.max(16, ...allKeepers.map((keeper) => keeper.round));
  const initialFilters = { search: '', position: '', tier: '', minRound: 1, maxRound, teamIds: [], sort: 'round' };
  const [filters, setFilters] = useState(initialFilters);
  const update = (key, value) => setFilters((current) => ({ ...current, [key]: value }));
  const columns = filterKeeperTeams(data.teams, filters);
  const keepers = columns.flatMap((team) => team.eligible_keepers);
  const positions = [...new Set(allKeepers.flatMap((keeper) => keeper.player.positions))].sort();
  const rounds = Array.from({ length: maxRound }, (_, index) => index + 1);
  const toggleTeam = (id) => setFilters((current) => ({ ...current,
    teamIds: current.teamIds.includes(id) ? current.teamIds.filter((teamId) => teamId !== id) : [...current.teamIds, id],
  }));
  return <>
    <section className="page-heading">
      <p className="eyebrow">Scout the league’s keeper options</p>
      <h1>Keeper comparison</h1>
      <p className="muted">Compare eligible players and round costs across teams. Narrow the board to the positions, tiers, and teams you want to explore.</p>
      <KeeperStatus metadata={data.metadata} />
    </section>
    <section className="panel keeper-controls" aria-label="Keeper comparison filters">
      <div className="keeper-filter-grid">
        <label className="keeper-search">Find a player or team<input type="search" value={filters.search} onChange={(event) => update('search', event.target.value)} placeholder="Player, NFL team, or league team" /></label>
        <label>Position<select value={filters.position} onChange={(event) => update('position', event.target.value)}><option value="">All positions</option>{positions.map((position) => <option key={position}>{position}</option>)}</select></label>
        <label>Tier<select value={filters.tier} onChange={(event) => update('tier', event.target.value)}><option value="">All tiers</option>{['gold', 'silver', 'bronze'].map((tier) => <option key={tier} value={tier}>{tier[0].toUpperCase() + tier.slice(1)}</option>)}</select></label>
        <label>From round<select value={filters.minRound} onChange={(event) => {
          const minRound = Number(event.target.value);
          setFilters((current) => ({ ...current, minRound, maxRound: Math.max(minRound, current.maxRound) }));
        }}>{rounds.map((round) => <option key={round} value={round}>{round}</option>)}</select></label>
        <label>Through round<select value={filters.maxRound} onChange={(event) => {
          const maxRound = Number(event.target.value);
          setFilters((current) => ({ ...current, maxRound, minRound: Math.min(maxRound, current.minRound) }));
        }}>{rounds.map((round) => <option key={round} value={round}>{round}</option>)}</select></label>
        <label>Sort players<select value={filters.sort} onChange={(event) => update('sort', event.target.value)}><option value="round">Eligible round</option><option value="name">Player name</option></select></label>
      </div>
      <div className="keeper-team-controls">
        <details className="keeper-team-picker">
          <summary>{filters.teamIds.length ? `Comparing ${filters.teamIds.length} ${filters.teamIds.length === 1 ? 'team' : 'teams'}` : 'Comparing all teams'} <span className="muted">· Choose teams</span></summary>
          <fieldset><legend className="visually-hidden">Teams to compare</legend><p className="muted small-note">Choose teams to compare side by side. With none selected, the board shows everyone.</p>
            <div className="keeper-team-options">{[...data.teams].sort((a, b) => a.name.localeCompare(b.name)).map((team) => <label key={team.team_id}><input type="checkbox" checked={filters.teamIds.includes(String(team.team_id))} onChange={() => toggleTeam(String(team.team_id))} />{team.name}</label>)}</div>
          </fieldset>
        </details>
        <button className="text-button" onClick={() => setFilters(initialFilters)}>Clear filters</button>
      </div>
    </section>
    <div className="keeper-board-stats" role="status" aria-live="polite">
      <span><strong>{keepers.length}</strong> of {allKeepers.length} keepers · {columns.length} {columns.length === 1 ? 'team' : 'teams'}</span>
      <div>{['gold', 'silver', 'bronze'].map((tier) => <span className={`tier-badge tier-${tier}`} key={tier}>{tier} {keepers.filter((keeper) => keeper.tier === tier).length}</span>)}</div>
    </div>
    {keepers.length ? <>
      <p className="muted keeper-board-hint">Scroll across to compare teams, or choose teams above. Round numbers are keeper costs.</p>
      <div className="keeper-board-scroll" role="region" aria-label="Keeper comparison board" tabIndex="0">
        <div className="keeper-board-columns">{columns.map((team) => <section className="keeper-team-column" key={team.team_id} aria-label={`${team.name} keepers`}>
          <header className="keeper-column-header"><a className="team-link" href={teamHref(team)}><img src={team.logo_image} alt="" loading="lazy" />{team.name}</a><span className="muted">{team.eligible_keepers.length} matching {team.eligible_keepers.length === 1 ? 'keeper' : 'keepers'}</span></header>
          <div className="keeper-column-players" role="region" aria-label={`${team.name} eligible players`} tabIndex="0">{team.eligible_keepers.length ? <ul>{team.eligible_keepers.map((keeper) => <li className="comparison-keeper" key={keeper.player.yahoo_player_key ?? keeper.player.name}>
            <div className="comparison-player"><img src={keeper.player.headshot_image} alt="" loading="lazy" /><div><h2><PlayerName player={keeper.player} /></h2><span className="muted">{keeper.player.team} · {keeper.player.positions.join(', ')}</span></div></div>
            <div className="comparison-cost"><span>Round <strong>{keeper.round}</strong></span><span className={`tier-badge tier-${keeper.tier}`}>{keeper.tier}</span></div>
            <p className="draft-history">{keeper.draft_status}</p>
          </li>)}</ul> : <p className="muted keeper-column-empty">No keepers match these filters.</p>}</div>
        </section>)}</div>
      </div>
    </> : <section className="panel keeper-board-empty"><h2>No keepers match these filters</h2><p className="muted">Try another position, tier, round range, or team selection.</p><button className="retry-button" onClick={() => setFilters(initialFilters)}>Show all keepers</button></section>}
    <KeeperPickupCandidates data={data} />
  </>;
}
