import { playerProduction, rollingPercentage } from './dashboardData';
import { positionFor, positionStyles } from './positionStyles';

const hundredths = (value) => Math.round(Number(value) * 100);
const isRegular = (matchup) => !matchup.matchup_type || matchup.matchup_type === 'regular';

export function positionProduction(team, matchups) {
  const totals = new Map();
  for (const player of playerProduction(team, matchups)) {
    const { label } = positionFor(player);
    totals.set(label, (totals.get(label) ?? 0) + player.pointHundredths);
  }
  return Object.entries(positionStyles)
    .filter(([position]) => totals.has(position))
    .map(([position, style]) => ({ ...style, points: totals.get(position) / 100 }));
}

export function scheduleLuck(team) {
  const games = (team.wins ?? 0) + (team.losses ?? 0) + (team.ties ?? 0);
  const allPlayGames = (team.rolling_wins ?? 0) + (team.rolling_losses ?? 0) + (team.rolling_ties ?? 0);
  if (!games || !allPlayGames) return null;
  const actual = ((team.wins ?? 0) + (team.ties ?? 0) / 2) / games;
  const allPlay = rollingPercentage(team);
  return { actual, allPlay, gap: actual - allPlay, extraWins: (actual - allPlay) * games, games };
}

// Prize amounts and ranking metrics match the notebook's existing regular-season awards.
export const raceCategories = [
  { key: 'regular_season_record', title: 'Regular Season record race', metric: 'wins', label: 'Wins', prizes: [40, 15] },
  { key: 'regular_season_points', title: 'Regular Season points race', metric: 'points_for', label: 'Points', prizes: [50, 30] },
];

export function payoutRace(teams, category) {
  const rows = [...teams].sort((a, b) => b[category.metric] - a[category.metric] || a.name.localeCompare(b.name));
  const best = rows[0]?.[category.metric] ?? 0;
  const cutoff = rows[Math.min(1, rows.length - 1)]?.[category.metric] ?? 0;
  let rank;
  return rows.map((team, index) => {
    const value = team[category.metric];
    if (index === 0 || value !== rows[index - 1][category.metric]) rank = index + 1;
    return {
      team, value, rank,
      behindLeader: Math.round((best - value) * 100) / 100,
      behindPayout: Math.round(Math.max(0, cutoff - value) * 100) / 100,
      tied: rows.some((other) => other !== team && other[category.metric] === value),
      earned: (team.payout_items ?? []).filter((item) => item.category === category.key)
        .reduce((sum, item) => sum + item.amount, 0),
    };
  });
}

function extreme(entries, key, highest = true) {
  if (!entries.length) return [];
  const best = (highest ? Math.max : Math.min)(...entries.map((entry) => entry[key]));
  return entries.filter((entry) => Math.abs(entry[key] - best) < 1e-9);
}

export function seasonAwards(data) {
  const appearances = [];
  const wins = [];
  const losses = [];
  const findTeam = (entry) => data.teams.find((team) =>
    team.team_id != null && entry.team_id != null
      ? String(team.team_id) === String(entry.team_id) : team.name === entry.name
  ) ?? entry;
  for (const matchup of data.matchups) {
    if (!isRegular(matchup) || !matchup.team0 || !matchup.team1) continue;
    for (const [side, other] of [['team0', 'team1'], ['team1', 'team0']]) {
      const score = hundredths(matchup[side].points);
      const against = hundredths(matchup[other].points);
      if (!Number.isFinite(score) || !Number.isFinite(against)) continue;
      const entry = {
        team: findTeam(matchup[side]), opponent: findTeam(matchup[other]), week: matchup.week,
        points: score / 100, against: against / 100, margin: Math.abs(score - against) / 100,
      };
      appearances.push(entry);
      if (score > against) wins.push(entry);
      if (score < against) losses.push(entry);
    }
  }
  const efficiency = data.teams.filter((team) => team.optimal_points_for > 0 && Number.isFinite(team.points_for))
    .map((team) => ({ team, efficiency: team.points_for / team.optimal_points_for * 100 }));
  return [
    { key: 'high_score', title: 'High score', metric: 'points', unit: 'points', entries: extreme(appearances, 'points') },
    { key: 'biggest_win', title: 'Biggest win', metric: 'margin', unit: 'point margin', entries: extreme(wins, 'margin') },
    { key: 'closest_loss', title: 'Closest loss', metric: 'margin', unit: 'point margin', entries: extreme(losses, 'margin', false) },
    { key: 'high_loss', title: 'Highest-scoring loss', metric: 'points', unit: 'points', entries: extreme(losses, 'points') },
    { key: 'low_win', title: 'Lowest-scoring win', metric: 'points', unit: 'points', entries: extreme(wins, 'points', false) },
    { key: 'efficiency', title: 'Best lineup efficiency', metric: 'efficiency', unit: '% of optimal points', entries: extreme(efficiency, 'efficiency') },
  ];
}

// Same ordering as the league overview: wins, ties, then points for.
// Equal records and points remain tied at the playoff boundary.
export function playoffPicture(data) {
  const spots = data.metadata?.playoff_teams ?? 6;
  const startWeek = data.metadata?.playoff_start_week ?? 15;
  const sorted = [...data.teams].sort((a, b) =>
    b.wins - a.wins || (b.ties ?? 0) - (a.ties ?? 0) || b.points_for - a.points_for || a.name.localeCompare(b.name));
  const sameStanding = (a, b) => a && b && a.wins === b.wins && (a.ties ?? 0) === (b.ties ?? 0) && a.points_for === b.points_for;
  let rank;
  const rows = sorted.map((team, index) => {
    if (!sameStanding(team, sorted[index - 1])) rank = index + 1;
    const tied = sameStanding(team, sorted[index - 1]) || sameStanding(team, sorted[index + 1]);
    const boundary = sorted[spots - 1];
    const cutoffTied = Boolean(boundary && sorted[spots] && sameStanding(boundary, sorted[spots]) && sameStanding(team, boundary));
    return { team, rank, tied: Boolean(tied), cutoffTied };
  });
  return {
    spots, startWeek,
    started: (data.metadata?.latest_completed_week ?? data.weeks ?? 0) >= startWeek,
    field: rows.filter((row) => row.rank <= spots),
    draftChoices: rows.filter((row) => row.rank > spots).map((row) => ({ ...row, choice: row.rank - spots })),
    draftCutoffTied: rows.some((row) => row.cutoffTied),
  };
}

export function playoffStandings(teams, metadata = {}) {
  const picture = playoffPicture({ teams, metadata });
  const cutoff = picture.field[picture.field.length - 1]?.team;
  const regularSeasonGames = (metadata.playoff_start_week ?? 15) - 1;
  const played = (team) => (team.wins ?? 0) + (team.losses ?? 0) + (team.ties ?? 0);
  const winEquivalents = (team) => (team.wins ?? 0) + (team.ties ?? 0) / 2;
  const finished = teams.length > 0 && teams.every((team) => played(team) >= regularSeasonGames);
  const inField = new Set(picture.field.map((row) => row.team.team_id ?? row.team.name));
  return teams.map((team) => {
    const inPosition = inField.has(team.team_id ?? team.name);
    const remaining = Math.max(0, regularSeasonGames - played(team));
    // A tied record can still qualify through points for. Only a strictly
    // unreachable record eliminates a team before all games are complete.
    const eliminationNumber = inPosition || !cutoff ? null : finished ? 0 : Math.max(0,
      Math.floor(winEquivalents(team) + remaining - winEquivalents(cutoff)) + 1);
    const gamesBack = !cutoff || inPosition ? 0 : Math.max(0,
      ((cutoff.wins ?? 0) - (team.wins ?? 0) + (team.losses ?? 0) - (cutoff.losses ?? 0)) / 2);
    // To guarantee a place, fewer than `spots` other teams may be able
    // to match our record. Use the sixth-highest rival ceiling for six spots,
    // excluding this team, and preserve all unknown points-for tiebreaks.
    const rivalCeilings = teams.filter((other) => other !== team)
      .map((other) => winEquivalents(other) + Math.max(0, regularSeasonGames - played(other)))
      .sort((a, b) => b - a);
    const rivalCeiling = rivalCeilings[picture.spots - 1];
    const cutoffTied = picture.field.some((row) => row.team === team && row.cutoffTied);
    const magicNumber = !inPosition ? null : finished && !cutoffTied ? 0
      : rivalCeiling == null ? 0 : Math.max(0, Math.floor(rivalCeiling - winEquivalents(team)) + 1);
    const status = finished && cutoffTied ? 'tiebreak'
      : magicNumber === 0 ? 'clinched' : eliminationNumber === 0 ? 'out'
        : inPosition ? 'magic' : 'elimination';
    return {
      ...team, playoff_games_back: gamesBack, elimination_number: eliminationNumber,
      magic_number: magicNumber, playoff_in_position: inPosition, playoff_status: status,
      playoff_number: status === 'tiebreak' ? null : magicNumber ?? eliminationNumber,
    };
  });
}
