import React, { useMemo, useState } from 'react';
import { PlayerName } from './PlayerHistoryDialog';
import { formatPoints, playerProduction } from './dashboardData';
import { contributionColors, productionByPosition } from './contributionData';
import ContributionPie from './ContributionPie';

function PositionPieCard({ group }) {
  const [selected, setSelected] = useState(null);
  const segments = group.players.map((player, index) => ({
    key: player.key, name: player.name, points: player.points, color: contributionColors[index % contributionColors.length],
  }));
  return <article className="position-player-card" aria-label={`${group.position} player contributions`}>
    <div className="section-heading"><h3>{group.position}</h3><span className="muted">{formatPoints(group.net)} net pts</span></div>
    <div className="position-player-layout">
      <ContributionPie segments={segments} activeKey={selected} label={`${group.position} production by player. ${group.players.map((player) => `${player.name}: ${formatPoints(player.points)} points, ${group.share(player) == null ? 'share unavailable' : `${(group.share(player) * 100).toFixed(1)}%`}`).join('; ')}`} />
      <ul className="contribution-legend">{group.players.map((player, index) => <li key={player.key}>
        <button type="button" className="contribution-swatch" style={{ background: segments[index].color }} aria-label={`Highlight ${player.name}`} aria-pressed={selected === player.key} onClick={() => setSelected(selected === player.key ? null : player.key)} />
        <div><PlayerName player={player} /><span className="muted">{formatPoints(player.points)} pts · {player.starts} {player.starts === 1 ? 'start' : 'starts'}</span></div>
        <strong>{group.share(player) == null ? '—' : `${(group.share(player) * 100).toFixed(1)}%`}</strong>
      </li>)}</ul>
    </div>
    {group.hasNegative && <p className="muted contribution-note">Slices and percentages use positive player totals. Negative totals remain in the legend and net points.</p>}
    {!group.positive && <p className="muted contribution-note">No positive starter points to divide yet.</p>}
  </article>;
}

export default function PositionPlayerPies({ team, matchups }) {
  const groups = useMemo(() => productionByPosition(playerProduction(team, matchups)), [team, matchups]);
  return <section className="panel" aria-labelledby="position-player-pies-title">
    <div className="section-heading"><div><p className="eyebrow">The players behind each position</p><h2 id="position-player-pies-title">Position contributions</h2></div></div>
    <p className="muted small-note">Each pie divides one position’s regular-season starter points among its players. Includes former players; excludes bench, IR, and postseason points. FLEX starts count at the player’s football position.</p>
    {groups.length ? <div className="contribution-grid">{groups.map((group) => <PositionPieCard key={group.position} group={group} />)}</div> : <p className="empty-state">No regular-season starts yet.</p>}
  </section>;
}
