import React, { useId, useMemo, useState } from 'react';
import { PlayerName } from './PlayerHistoryDialog';
import { formatPoints } from './dashboardData';
import { positionStyles } from './positionStyles';
import { baselineRanks, rosterBaselineRanks, draftProduction, positionalBaselines, productionAboveBaseline, scatterLayout } from './draftProductionData';

import { weeklyDraftProduction } from './draftWeeklyProduction';
import { fitDraftTrend } from './draftTrend';

const draftLabel = (player) => player.draftUnknown ? 'Unknown draft cost' : player.undrafted ? 'Undrafted' : `${player.draft.pick ? `Pick ${player.draft.pick} · ` : ''}Round ${player.draft.round}`;

export default function DraftProduction({ data }) {
  const [includeBench, setIncludeBench] = useState(false);
  const [includeFullPeriod, setIncludeFullPeriod] = useState(false);
  const [metric, setMetric] = useState('points');
  const [includeKeepers, setIncludeKeepers] = useState(true);
  const [position, setPosition] = useState('All');
  const [search, setSearch] = useState('');
  const [selectedKey, setSelectedKey] = useState(null);
  const [showTrend, setShowTrend] = useState(false);
  const trendClipId = useId();
  const fullProduction = useMemo(() => draftProduction(data, true), [data]);
  const completeProduction = useMemo(() => draftProduction(data, true, true), [data]);
  const baselineUsesFull = completeProduction?.fullPeriodComplete === true;
  const fullPeriodMode = includeFullPeriod && baselineUsesFull;
  const production = useMemo(() => fullPeriodMode ? completeProduction : includeBench ? fullProduction : draftProduction(data), [data, includeBench, fullProduction, fullPeriodMode, completeProduction]);
  const ranks = metric === 'rosterValue' ? rosterBaselineRanks : baselineRanks;
  const baselines = useMemo(() => positionalBaselines(baselineUsesFull ? completeProduction : fullProduction, ranks), [baselineUsesFull, completeProduction, fullProduction, ranks]);
  const weeklyMode = metric === 'weeklyStarter' || metric === 'weeklyElite';
  const valueMode = metric === 'value' || metric === 'rosterValue';
  const weeklyProduction = useMemo(() => weeklyMode ? weeklyDraftProduction(data, metric === 'weeklyElite' ? 'elite' : 'starter') : null, [data, weeklyMode, metric]);
  const historical = Boolean(fullProduction?.historical);
  const baselineGroups = historical ? Object.entries(baselines) : [[null, baselines]];
  const hasBaseline = (label) => baselineGroups.some(([, group]) => Boolean(group[label]?.player));
  const model = useMemo(() => weeklyMode ? weeklyProduction : valueMode ? productionAboveBaseline(production, baselines) : production, [weeklyMode, weeklyProduction, valueMode, production, baselines]);
  const productionLabel = fullPeriodMode ? 'Starter + bench + free agent points' : includeBench ? 'Starter + bench points' : 'Starter points';
  const scoreLabel = weeklyMode ? `${metric === 'weeklyElite' ? 'Elite' : 'Starter'}-level weeks` : valueMode ? 'Points above baseline' : productionLabel;
  const playerScore = (player) => weeklyMode ? `${player.points} of ${player.seasonWeeks} weeks (${player.weekPercentage.toFixed(0)}%)` : `${score(player.points)} ${valueMode ? 'points above baseline' : 'points'}`;
  const score = (points) => `${valueMode && points > 0 ? '+' : ''}${formatPoints(points)}`;
  const players = useMemo(() => (model?.players ?? []).filter((player) => (position === 'All' || player.position === position)
    && (includeKeepers || !player.isKeeper)
    && player.name.toLowerCase().includes(search.trim().toLowerCase())), [model, position, search, includeKeepers]);
  const trend = useMemo(() => showTrend ? fitDraftTrend(players) : null, [showTrend, players]);
  // Keep scales fixed while filtering so dot positions remain comparable.
  const allLayout = useMemo(() => {
    if (!model) return null;
    const layout = scatterLayout(model.players, model.maxDraft);
    if (!weeklyMode) return layout;
    const max = Math.max(1, model.seasonWeeks);
    const y = (value) => layout.bottom - value / max * (layout.bottom - layout.top);
    return { ...layout, min: 0, max, y, points: layout.points.map((p) => ({ ...p, cy: y(p.points) })) };
  }, [model, weeklyMode]);
  const visibleKeys = new Set(players.map((player) => player.key));
  const selected = players.find((player) => player.key === selectedKey) ?? [...players].sort((a, b) => b.points - a.points)[0];
  const ticks = model?.roundTicks ?? [];
  const trendPath = trend && allLayout ? Array.from({ length: 121 }, (_, i) => {
    const x = trend.firstX + (trend.lastX - trend.firstX) * i / 120;
    return `${i ? 'L' : 'M'}${allLayout.x(x)},${allLayout.y(trend.predict(x))}`;
  }).join(' ') : null;
  return <>
    <section className="page-heading"><p className="eyebrow">What did each draft investment produce?</p><h1>{historical ? 'Historical draft production' : 'Draft production'}</h1><p className="muted">{historical ? '2024–2025 combined · Each dot is one player-season. Value is measured against the baseline from that same season.' : 'Compare draft cost with points scored across the league, including players who changed fantasy teams.'}</p></section>
    <section className="panel draft-production-panel" aria-labelledby="draft-production-title">
      <div className="section-heading"><div><h2 id="draft-production-title">Production by draft round</h2><p className="muted small-note">Regular season · {weeklyMode ? scoreLabel : productionLabel} · One dot per {historical ? 'player-season' : 'player'}</p></div>
      </div>
      {!model ? <p className="empty-state">Full draft results aren’t included in this season’s export yet. Run the updated data notebook to add them. For a local preview, select the current season’s data.</p> : <>
        <div className="draft-chart-toggles" role="group" aria-label="Draft chart options"><div className="draft-toggle-group" role="group" aria-label="Values to show"><span className="draft-toggle-label">Values to show</span><div className="contribution-toggle">{[['points', 'Raw points'], ['value', 'Value above starter'], ['rosterValue', 'Value above roster'], ['weeklyStarter', 'Starter-level weeks'], ['weeklyElite', 'Elite-level weeks']].map(([value, label]) => <button type="button" key={value} aria-pressed={metric === value} onClick={() => { setMetric(value); if (value.startsWith('weekly') && position !== 'All' && !baselineRanks[position]) setPosition('All'); if (['value', 'rosterValue'].includes(value) && !baselineGroups.some(([, group]) => group[position]?.availablePlayers >= (value === 'rosterValue' ? rosterBaselineRanks : baselineRanks)[position])) setPosition('All'); }}>{label}</button>)}</div></div>
          {!weeklyMode && <div className="draft-toggle-group" role="group" aria-label="Which points to include"><span className="draft-toggle-label">Which points to include</span><div className="contribution-toggle">{[[false, 'Starter'], [true, 'Starter + bench']].map(([value, label]) => <button type="button" key={String(value)} aria-pressed={!fullPeriodMode && includeBench === value} onClick={() => { setIncludeFullPeriod(false); setIncludeBench(value); }}>{label}</button>)}<button type="button" aria-pressed={fullPeriodMode} disabled={!baselineUsesFull} onClick={() => setIncludeFullPeriod(true)} title={baselineUsesFull ? 'All regular-season scores, including weeks before pickups' : 'Collect the remaining weekly scores to enable full-period totals'}>Starter + bench + free agent</button></div></div>}
          <div className="draft-toggle-group" role="group" aria-label="Players to show"><span className="draft-toggle-label">Players to show</span><div className="contribution-toggle">{[[true, 'Include keepers'], [false, 'Exclude keepers']].map(([value, label]) => <button type="button" key={String(value)} aria-pressed={includeKeepers === value} onClick={() => setIncludeKeepers(value)}>{label}</button>)}</div></div>
        </div>
        <label className="draft-trend-toggle"><input type="checkbox" checked={showTrend} onChange={(event) => setShowTrend(event.target.checked)} /> Show trend curve</label>
        <div className="draft-chart-controls"><label>Position<select value={position} onChange={(event) => setPosition(event.target.value)}><option>All</option>{Object.keys(positionStyles).filter((label) => production.players.some((player) => player.position === label)).map((label) => <option key={label} disabled={weeklyMode ? !baselineRanks[label] : valueMode && !hasBaseline(label)}>{label}</option>)}</select></label>
          <label>Find a player<input type="search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Player name" /></label><span className="muted">{players.length} {historical ? 'player-seasons' : 'players'}</span></div>
        {!includeKeepers && <p className="muted contribution-note">Kept players are hidden using their recorded Yahoo keeper flag. Positional baselines and chart scales still include all players.</p>}
        <ul className="production-legend" aria-label="Draft chart position colors">{Object.entries(positionStyles).filter(([label]) => model.players.some((player) => player.position === label)).map(([label, style]) => <li key={label} style={{ '--position-color': style.color }}><span aria-hidden="true" />{label}</li>)}</ul>
        {weeklyMode && <div className="draft-trend-summary">
          <strong>{scoreLabel}</strong>
          <p className="muted small-note">A qualifying week finishes among the top {metric === 'weeklyElite' ? '6 QBs, 12 RBs, 12 WRs, or 6 TEs' : '12 QBs, 30 RBs, 30 WRs, or 12 TEs'} in that week’s scoring. Ties at the cutoff qualify; zero or negative scores do not.</p>
          <p className="muted small-note">Uses all available scores regardless of starter, bench, IR, or free-agent status. Rankings include players recorded on a league roster at some point this season. Percentages use all recorded regular-season weeks, including byes and missed games. Thresholds are calculated separately for each season and stay fixed when filtering.</p>
          {!baselineUsesFull && <p className="muted small-note">Weekly score coverage is incomplete; missing scores can affect ranks and counts.</p>}
        </div>}
        {valueMode && <div className="draft-baselines">
          <p className="muted contribution-note">{metric === 'rosterValue' ? 'Roster baseline: QB25, RB56, WR61, TE21, based on typical starter + bench roster counts excluding IR.' : 'Starter baseline: QB13, RB31, WR31, TE13, including an allowance for FLEX starters.'}</p>
          <p className="muted contribution-note">Value = {productionLabel.toLowerCase()} minus the positional baseline’s {baselineUsesFull ? 'full-period points, including unrostered weeks' : 'starter + bench points'}. Baselines stay fixed when toggling production or filtering. K and DEF have no assigned baseline and are excluded.</p>
          {baselineGroups.map(([season, group]) => <div key={season ?? 'current'}>{season && <h3 className="historical-baseline-year">{season} baselines</h3>}<ul aria-label={season ? `${season} positional baselines` : 'Positional baselines'}>{Object.values(group).map((baseline) => <li key={baseline.position}><strong>{baseline.position}{baseline.rank}</strong>{baseline.player ? <><PlayerName player={baseline.player} /><span>{formatPoints(baseline.player.points)} pts</span></> : <span className="muted">Unavailable · {baseline.availablePlayers} recorded players</span>}</li>)}</ul></div>)}
          <p className="muted contribution-note">{baselineUsesFull ? 'Ranks use complete regular-season scores for known players, regardless of fantasy ownership or lineup slot.' : 'Ranks use recorded regular-season starter + bench points; missing unrostered weeks are excluded.'} This subtracts the entire period’s baseline even if a player missed games or was benched. Positions with too few recorded players are omitted. Players never recorded on league rosters are outside this ranking pool.</p>
        </div>}
        {historical && allLayout.hasUnknown && <p className="historical-coverage">Saved draft costs are known for {model.players.filter((player) => !player.draftUnknown).length} of {model.players.length} player-seasons. Missing costs appear in a separate “Unknown cost” lane and are not treated as undrafted.</p>}
        <p className="muted contribution-note">Select a dot or use the player list below for details. Undrafted players share the shaded area on the right.</p>
        {showTrend && <div className="draft-trend-summary" aria-live="polite">{trend ? <>
          <strong>Exponential trend</strong>
          <p className="draft-trend-equation">y = {trend.offset.toFixed(2)} + {trend.amplitude.toFixed(2)} × e<sup>−{trend.rate.toPrecision(4)} × (x − {trend.firstX})</sup></p>
          <p className="muted small-note">x = {model.exactPicks ? 'overall draft pick' : 'draft round'} · y = {scoreLabel.toLowerCase()} · R² = {trend.rSquared.toFixed(3)} · {trend.count} drafted {historical ? 'player-seasons' : 'players'}</p>
          <p className="muted small-note">Fits visible drafted players only; undrafted and unknown-cost players are excluded. Higher R² means the curve explains more of the variation. This is a descriptive trend, not a prediction.</p>
        </> : <p className="muted small-note">No decay curve available for this selection. A fit needs at least 8 drafted players across 4 draft positions, variation in points, and a decreasing trend.</p>}</div>}
        <div className="draft-scatter-scroll" role="region" aria-label="Draft production scatterplot" tabIndex="0">
          <svg className="draft-scatter" viewBox={`0 0 ${allLayout.width} ${allLayout.height}`} role="group" aria-label={`Player production by ${model.exactPicks ? 'overall draft pick' : 'draft round'}`}>
            {allLayout.hasUnknown && <rect x="1034" y={allLayout.top} width="115" height={allLayout.bottom - allLayout.top} rx="8" className="draft-undrafted-zone" />}
            <rect x="894" y={allLayout.top} width="115" height={allLayout.bottom - allLayout.top} rx="8" className="draft-undrafted-zone" />
            {[...new Set(Array.from({ length: 6 }, (_, i) => weeklyMode ? Math.round(allLayout.max * i / 5) : allLayout.min + (allLayout.max - allLayout.min) * i / 5))].map((value, i) => <g key={i} aria-hidden="true"><line x1={allLayout.left} x2={allLayout.right} y1={allLayout.y(value)} y2={allLayout.y(value)} className="draft-grid-line" /><text x={allLayout.left - 12} y={allLayout.y(value) + 4} textAnchor="end">{value.toFixed(0)}</text></g>)}
            <line x1={allLayout.left} x2={allLayout.right} y1={allLayout.y(0)} y2={allLayout.y(0)} className="draft-zero-line" aria-hidden="true" />
            {ticks.map((tick) => <text key={tick.round} x={allLayout.x(tick.x)} y={allLayout.bottom + 24} textAnchor="middle" aria-hidden="true">{tick.round}</text>)}
            <text x={allLayout.undraftedX} y={allLayout.bottom + 24} textAnchor="middle" aria-hidden="true">Undrafted</text>
            {allLayout.hasUnknown && <text x={allLayout.unknownX} y={allLayout.bottom + 24} textAnchor="middle" aria-hidden="true">Unknown cost</text>}
            <text x="465" y="465" textAnchor="middle" className="draft-axis-title" aria-hidden="true">Draft round{model.exactPicks ? ' · dots spaced by exact pick' : ' · earlier rounds → later rounds'}</text>
            <text transform="translate(18 220) rotate(-90)" textAnchor="middle" className="draft-axis-title" aria-hidden="true">{scoreLabel}</text>
            {trendPath && <>
              <defs><clipPath id={trendClipId}><rect x={allLayout.left} y={allLayout.top} width={allLayout.draftRight - allLayout.left} height={allLayout.bottom - allLayout.top} /></clipPath></defs>
              <path d={trendPath} className="draft-trend-line" clipPath={`url(#${trendClipId})`} role="img" aria-label={`Exponential trend curve, R squared ${trend.rSquared.toFixed(3)}`} />
            </>}
            {allLayout.points.filter((point) => visibleKeys.has(point.key)).sort((a, b) => Number(a.key === selected?.key) - Number(b.key === selected?.key)).map((point) => <circle key={point.key} cx={point.cx} cy={point.cy} r={point.key === selected?.key ? 7 : 5} fill={point.color} className={`draft-player-dot${point.key === selected?.key ? ' selected' : ''}`} tabIndex="0" role="button" aria-pressed={point.key === selected?.key}
              aria-label={`${point.name}${point.season ? ` (${point.season})` : ''}, ${point.position}, ${draftLabel(point)}, ${playerScore(point)}`} onClick={() => setSelectedKey(point.key)} onKeyDown={(event) => { if (['Enter', ' '].includes(event.key)) { event.preventDefault(); setSelectedKey(point.key); } }}>
              <title>{point.name}{point.season ? ` (${point.season})` : ''} · {point.position} · {draftLabel(point)} · {playerScore(point)}</title>
            </circle>)}
          </svg>
        </div>
        {selected ? <div className="draft-player-detail" aria-live="polite">
          {selected.headshot_image && <img src={selected.headshot_image} alt="" />}
          <div><strong><PlayerName player={selected} />{selected.season && ` · ${selected.season}`}</strong><p className="muted">{selected.position} · {draftLabel(selected)}{selected.draft?.team_name ? ` · Drafted by ${selected.draft.team_name}` : ''}</p>{valueMode && <p className="muted">{formatPoints(selected.rawPoints)} credited pts − {formatPoints(selected.baseline.player.points)} baseline pts</p>}</div><div className="draft-detail-score"><strong>{weeklyMode ? `${selected.points} / ${selected.seasonWeeks} weeks` : `${score(selected.points)} pts`}</strong>{weeklyMode && <span>{selected.weekPercentage.toFixed(0)}% of season weeks</span>}<span className="muted">{scoreLabel}</span></div>
        </div> : <p className="empty-state">No players match these filters.</p>}
        {weeklyMode && selected && <p className="muted small-note">Qualifying weeks: {selected.qualifyingWeeks.join(', ') || 'None'} · Scores available for {selected.observedWeeks} of {selected.seasonWeeks} weeks.{selected.unavailableWeeks > 0 && ` Insufficient players to establish the positional cutoff in ${selected.unavailableWeeks} weeks; those weeks do not count as qualifying.`}</p>}
        {!weeklyMode && <p className="muted small-note">{fullPeriodMode ? 'Full-period points include regular-season scores before pickups, while unrostered, and in every lineup slot.' : 'Points include regular-season weeks recorded on league rosters, wherever the player was owned. IR points are excluded.'} Postseason points are excluded. Keepers use their actual draft round, not next year’s keeper cost. Zero starter points can mean the player was only on the bench or IR.</p>}
        {!model.exactPicks && !historical && <p className="muted contribution-note">This export retains draft rounds. Exact overall pick numbers will be available after the next notebook export.</p>}
        <details className="draft-player-table"><summary>Player list · {players.length} players</summary><div className="table-scroll"><table><thead><tr><th scope="col">Player</th><th scope="col">Position</th><th scope="col">Draft cost</th><th scope="col">{scoreLabel}</th></tr></thead><tbody>{[...players].sort((a, b) => b.points - a.points || a.name.localeCompare(b.name)).map((player) => <tr key={player.key}><td><PlayerName player={player} />{player.season && ` · ${player.season}`}</td><td>{player.position}</td><td>{draftLabel(player)}</td><td>{weeklyMode ? playerScore(player) : score(player.points)}</td></tr>)}</tbody></table></div></details>
      </>}
    </section>
  </>;
}
