// Fit y = offset + amplitude * exp(-rate * (x - firstX)) in point space.
// For each decay rate, amplitude and offset have a closed-form least-squares fit.
export function fitDraftTrend(players) {
  const rows = players.filter((p) => p.draft && !p.undrafted && !p.draftUnknown
    && Number.isFinite(p.x) && Number.isFinite(p.points));
  if (rows.length < 8 || new Set(rows.map((p) => p.x)).size < 4) return null;
  const firstX = Math.min(...rows.map((p) => p.x));
  const lastX = Math.max(...rows.map((p) => p.x));
  const span = lastX - firstX;
  const mean = rows.reduce((sum, p) => sum + p.points, 0) / rows.length;
  const totalError = rows.reduce((sum, p) => sum + (p.points - mean) ** 2, 0);
  if (totalError < 1e-10) return null;
  const evaluate = (logRate) => {
    const rate = Math.exp(logRate) / span;
    const z = rows.map((p) => Math.exp(-rate * (p.x - firstX)));
    const zMean = z.reduce((sum, value) => sum + value, 0) / rows.length;
    let variance = 0, covariance = 0;
    rows.forEach((p, i) => {
      variance += (z[i] - zMean) ** 2;
      covariance += (z[i] - zMean) * (p.points - mean);
    });
    const amplitude = covariance / variance;
    if (!Number.isFinite(amplitude) || amplitude <= 0) return null;
    const offset = mean - amplitude * zMean;
    const error = rows.reduce((sum, p, i) => sum + (p.points - offset - amplitude * z[i]) ** 2, 0);
    return { rate, amplitude, offset, error, logRate };
  };
  const low = Math.log(.01), high = Math.log(20), step = (high - low) / 120;
  let best = null;
  for (let i = 0; i <= 120; i++) {
    const candidate = evaluate(low + step * i);
    if (candidate && (!best || candidate.error < best.error)) best = candidate;
  }
  if (!best) return null;
  let left = Math.max(low, best.logRate - step), right = Math.min(high, best.logRate + step);
  for (let i = 0; i < 36; i++) {
    const a = evaluate(left + (right - left) / 3);
    const b = evaluate(right - (right - left) / 3);
    if ((a?.error ?? Infinity) < (b?.error ?? Infinity)) right = right - (right - left) / 3;
    else left = left + (right - left) / 3;
    for (const candidate of [a, b]) if (candidate && candidate.error < best.error) best = candidate;
  }
  const rSquared = 1 - best.error / totalError;
  if (!Number.isFinite(rSquared) || rSquared < 1e-8) return null;
  return { ...best, firstX, lastX, count: rows.length, rSquared,
    predict: (x) => best.offset + best.amplitude * Math.exp(-best.rate * (x - firstX)) };
}
