import React, { useState } from 'react';
import { Card, Row, Col, Tab, Nav } from 'react-bootstrap';
import RosterTable from './RosterTable';

function WeeklyMatchups({ week, matchups, ranks }) {
  const [selectedMatchup, setSelectedMatchup] = useState(null);
  const [selectedTeam, setSelectedTeam] = useState(null); // Tracks selected team for Rank Order tab
  const [selectedSubTab, setSelectedSubTab] = useState("rankOrder"); // Tracks selected sub-tab

  const handleMatchupClick = (matchup) => {
    setSelectedMatchup(matchup);
    setSelectedTeam("team0"); // Default to team0 roster when a new matchup is selected
  };

  const handleTeamClick = (team) => {
    // Find the team within the selected week's matchups
    const weekMatchup = matchups.find(
      (m) => m.week === week && (m.team0.name === team.name || m.team1.name === team.name)
    );

    // Set the full team data based on whether it was team0 or team1
    if (weekMatchup) {
      const fullTeam = weekMatchup.team0.name === team.name ? weekMatchup.team0 : weekMatchup.team1;
      setSelectedTeam(fullTeam);
      setSelectedMatchup(null); // Clear any selected matchup
    }
  };

  const winnerAsSuccess = (val1, val2) => {
    return val1 > val2 ? "text-primary" : "text-light";
  };

  const weekMatchups = matchups.filter((matchup) => matchup.week === week);
  const weekRanking = ranks[week - 1] || []; // Get ranking data for the current week

  const selectedBorderStyle = { borderWidth: "5px" };

  return (
    <div>
      <h2 className="mb-4">Week {week}</h2>
      
      {/* Sub-Tabs for Rank Order and Matchups */}
      <Tab.Container activeKey={selectedSubTab} onSelect={(k) => setSelectedSubTab(k)}>
        <Nav variant="tabs" className="mb-3">
          <Nav.Item>
            <Nav.Link eventKey="rankOrder">Rank Order</Nav.Link>
          </Nav.Item>
          <Nav.Item>
            <Nav.Link eventKey="matchups">Matchups</Nav.Link>
          </Nav.Item>
        </Nav>

        <Tab.Content>
          {/* Rank Order Tab */}
          <Tab.Pane eventKey="rankOrder">
            <Row xs={1} className="g-3">
              {weekRanking.map((team, index) => (
                <Col key={index}>
                  <Card
                    className="text-center"
                    onClick={() => handleTeamClick(team)}
                    style={{ cursor: "pointer", ...(selectedTeam && selectedTeam.name === team.name ? selectedBorderStyle : {}) }}
                  >
                    <Card.Body className="d-flex align-items-center justify-content-between">
                      <div style={{ minWidth: "30px" }}>
                        <h5 className="mb-0" style={{ fontSize: '1.2rem', fontWeight: 'bold' }}>{index + 1}.</h5>
                      </div>
                      <div className="d-flex align-items-center" style={{ paddingLeft: '10px', flexGrow: 1 }}>
                        <img src={team.logo_image} alt={team.name} width="40" className="rounded-circle me-3" />
                        <div>
                          <h5 className="mb-0" style={{ fontSize: '1.2rem', fontWeight: 'bold' }}>{team.name}</h5>
                        </div>
                      </div>
                      <div>
                        <h5 className="mb-0" style={{ fontSize: '1.5rem', fontWeight: 'bold' }}>{team.points}</h5>
                      </div>
                    </Card.Body>
                  </Card>
                </Col>
              ))}
            </Row>

            {/* Display selected team's roster */}
            {selectedTeam && selectedTeam.roster && (
              <div className="mt-4">
                
                <h3 className="text-center mb-4">
                      {selectedTeam.name}
                </h3>
                <h4 className="text-center mb-4">
                      Selected Lineup Points: <span>{selectedTeam.points}</span> <br />
                      Optimal Lineup Points: <span>{selectedTeam.optimal_points}</span>
                </h4>  
                <RosterTable team={selectedTeam} />
              </div>
            )}
          </Tab.Pane>

          {/* Matchups Tab */}
          <Tab.Pane eventKey="matchups">
            <Row xs={1} md={2} className="g-4">
              {weekMatchups.map((matchup, index) => (
                <Col key={index}>
                  <Card 
                    className="text-center matchup-card" 
                    onClick={() => handleMatchupClick(matchup)}
                    style={{ cursor: "pointer", padding: "10px", ...(selectedMatchup === matchup && selectedTeam === "team0" ? selectedBorderStyle : {}) }}
                  >
                    {/* Conditionally render Card.Header if matchup_type is 'consolation' or 'playoff' */}
                    {(matchup.matchup_type === "consolation" || matchup.matchup_type === "playoff") && (
                      <Card.Header style={{ fontWeight: 'bold', fontSize: '1rem' }}>
                        {matchup.matchup_type === "consolation" ? "Consolation Game" : "Playoff Game"}
                      </Card.Header>
                    )}
                    <Card.Body>
                      <div className="d-flex justify-content-between align-items-center mb-3">
                        <img src={matchup.team0.logo_image} alt={matchup.team0.name} width="50" className="rounded-circle" />
                        <div className="ms-3 me-auto">
                          <p className="mb-0" style={{ fontSize: '1.2rem', fontWeight: 'bold' }}>{matchup.team0.name}</p>
                        </div>
                        <h5 className={winnerAsSuccess(matchup.team0.points, matchup.team1.points)} style={{ fontSize: '1.5rem', fontWeight: 'bold' }}>{matchup.team0.points}</h5>
                      </div>

                      <div className="d-flex justify-content-between align-items-center">
                        <img src={matchup.team1.logo_image} alt={matchup.team1.name} width="50" className="rounded-circle" />
                        <div className="ms-3 me-auto">
                          <p className="mb-0" style={{ fontSize: '1.2rem', fontWeight: 'bold' }}>{matchup.team1.name}</p>
                        </div>
                        <h5 className={winnerAsSuccess(matchup.team1.points, matchup.team0.points)} style={{ fontSize: '1.5rem', fontWeight: 'bold' }}>{matchup.team1.points}</h5>
                      </div>
                    </Card.Body>
                  </Card>
                </Col>
              ))}
            </Row>

            {/* Roster Display for Selected Matchup */}
            {selectedMatchup && (
            <div className="mt-4 roster-display">
                <h3 className="text-center mb-4">
                {selectedMatchup.team0.name} vs {selectedMatchup.team1.name}
                </h3>

                {/* Make the Row a flex container with nowrap and scroll */}
                <div style={{ overflowX: 'auto', display: 'flex', flexWrap: 'nowrap', gap: '1rem' }}>
                <div style={{ minWidth: '350px', flex: '0 0 50%' }}>
                    <h4 className="text-center mb-4">
                    Selected Lineup Points: <span className={winnerAsSuccess(selectedMatchup.team0.points, selectedMatchup.team1.points)}>{selectedMatchup.team0.points}</span> <br />
                    Optimal Lineup Points: <span className={winnerAsSuccess(selectedMatchup.team0.optimal_points, selectedMatchup.team1.optimal_points)}>{selectedMatchup.team0.optimal_points}</span>
                    </h4>
                    <RosterTable team={selectedMatchup.team0} />
                </div>
                <div style={{ minWidth: '350px', flex: '0 0 50%' }}>
                    <h4 className="text-center mb-4">
                    Selected Lineup Points: <span className={winnerAsSuccess(selectedMatchup.team1.points, selectedMatchup.team0.points)}>{selectedMatchup.team1.points}</span> <br />
                    Optimal Lineup Points: <span className={winnerAsSuccess(selectedMatchup.team1.optimal_points, selectedMatchup.team0.optimal_points)}>{selectedMatchup.team1.optimal_points}</span>
                    </h4>
                    <RosterTable team={selectedMatchup.team1} />
                </div>
                </div>
            </div>
            )}
          </Tab.Pane>
        </Tab.Content>
      </Tab.Container>
    </div>
  );
}

export default WeeklyMatchups;