import { positionFor } from './positionStyles';
import { normalizeData } from './dashboardData';

const inactive = ['BN', 'IR', 'IR+', 'IL', 'IL+', 'NA'];
const isStarted = (slot) => Boolean(slot) && !inactive.includes(slot);

function roundTicks(picks, exactPicks, rounds) {
  return Array.from({ length: rounds }, (_, i) => {
    const round = i + 1;
    const positions = picks.filter((pick) => pick.round === round).map((pick) => pick.pick);
    return { round, x: exactPicks && positions.length ? (Math.min(...positions) + Math.max(...positions)) / 2 : round };
  });
}

export const baselineRanks = { QB: 13, RB: 31, WR: 31, TE: 13 };

export const rosterBaselineRanks = { QB: 25, RB: 56, WR: 61, TE: 21 };

export function positionalBaselines(fullProduction, ranks = baselineRanks) {
  if (fullProduction?.seasons) return Object.fromEntries(Object.entries(fullProduction.seasons)
    .map(([season, production]) => [season, positionalBaselines(production, ranks)]));
  return Object.fromEntries(Object.entries(ranks).map(([position, rank]) => {
    const ranked = (fullProduction?.players ?? []).filter((player) => player.position === position)
      .sort((a, b) => b.points - a.points || a.key.localeCompare(b.key));
    return [position, { position, rank, player: ranked[rank - 1] ?? null, availablePlayers: ranked.length }];
  }));
}

export function productionAboveBaseline(production, baselines) {
  if (!production) return null;
  if (production.seasons) {
    const seasons = Object.fromEntries(Object.entries(production.seasons).map(([season, model]) => [season, productionAboveBaseline(model, baselines[season])]));
    return { ...production, seasons, players: Object.values(seasons).flatMap((model) => model.players) };
  }
  return { ...production, players: production.players.flatMap((player) => {
    const baseline = baselines[player.position];
    if (!baseline?.player) return [];
    return [{ ...player, rawPoints: player.points, baseline,
      points: (Math.round(player.points * 100) - Math.round(baseline.player.points * 100)) / 100 }];
  }) };
}

export function draftProduction(data, includeBench = false, includeUnrostered = false) {
  if (data.historical_seasons) {
    const seasons = {};
    for (const archive of data.historical_seasons) {
      const normalized = normalizeData(archive);
      normalized.teams = normalized.teams.map((team) => ({ ...team, historical: true }));
      const model = draftProduction(normalized, includeBench, includeUnrostered);
      if (!model) continue;
      const season = normalized.metadata.season;
      seasons[season] = { ...model, players: model.players.map((player) => ({ ...player, season, historyData: normalized })) };
    }
    if (!Object.keys(seasons).length) return null;
    const rounds = Math.max(...Object.values(seasons).map((model) => model.rounds));
    const exactPicks = Object.values(seasons).every((model) => model.exactPicks);
    if (!exactPicks) {
      // A combined chart must use one consistent unit across all seasons.
      for (const model of Object.values(seasons)) {
        model.players = model.players.map((player) => ({ ...player, x: player.draft?.round ?? null }));
      }
    }
    const picks = data.historical_seasons.flatMap((archive) => (archive.completed_draft ?? archive.historical_draft)?.picks ?? []);
    return { seasons, historical: true, exactPicks, rounds, roundTicks: roundTicks(picks, exactPicks, rounds),
      maxDraft: exactPicks ? Math.max(...Object.values(seasons).map((model) => model.maxDraft)) : rounds,
      fullPeriodComplete: Object.values(seasons).every((model) => model.fullPeriodComplete),
      players: Object.values(seasons).flatMap((model) => model.players) };
  }
  const draft = data.completed_draft ?? data.historical_draft;
  if ((!draft?.complete && !draft?.allow_partial) || Number(draft.season) !== Number(data.metadata?.season)) return null;
  const explicitlyUndrafted = new Set(draft.undrafted_player_keys ?? []);
  const supplemental = Number(data.player_week_points?.season) === Number(data.metadata?.season) ? data.player_week_points : null;
  const regularWeeks = new Set((data.matchups ?? []).filter((matchup) => !matchup.matchup_type || matchup.matchup_type === 'regular').map((matchup) => Number(matchup.week)));
  const picks = new Map(draft.picks.map((pick) => [pick.yahoo_player_key, pick]));
  const players = new Map();
  for (const matchup of data.matchups ?? []) {
    if (matchup.matchup_type && matchup.matchup_type !== 'regular') continue;
    for (const side of ['team0', 'team1']) {
      for (const player of matchup[side]?.roster ?? []) {
        // Cross-platform matching by name is unnecessary here: both are Yahoo.
        const key = player.yahoo_player_key;
        if (!key) continue;
        if (!players.has(key)) players.set(key, { key, player, latestWeek: -1, weeks: new Map(), isKeeper: false });
        const record = players.get(key);
        // Keep the original kept-player flag after trades or later flag changes.
        record.isKeeper = record.isKeeper || player.keeper === true || player.keeper === 1;
        if (Number(matchup.week) >= record.latestWeek) {
          record.player = player;
          record.latestWeek = Number(matchup.week);
        }
        const points = player.points == null ? null : Number(player.points);
        if (!Number.isFinite(points)) continue;
        const slot = player.selected_position;
        if (!includeUnrostered && !isStarted(slot) && !(includeBench && slot === 'BN')) continue;
        // A player-week counts once across roster moves or repeated exports.
        const previous = record.weeks.get(Number(matchup.week));
        const started = isStarted(slot);
        if (!previous || (started && !previous.started)) {
          record.weeks.set(Number(matchup.week), { points: Math.round(points * 100), started });
        }
      }
    }
  }
  if (includeUnrostered && supplemental) {
    for (const record of players.values()) {
      for (const [week, points] of Object.entries(supplemental.points?.[record.key] ?? {})) {
        if (regularWeeks.has(Number(week)) && !record.weeks.has(Number(week)) && points != null && Number.isFinite(Number(points))) {
          record.weeks.set(Number(week), { points: Math.round(Number(points) * 100), started: false });
        }
      }
    }
  }
  const exactPicks = draft.picks.length > 0 && draft.picks.every((pick) => Number.isInteger(pick.pick) && pick.pick > 0);
  const maxDraft = Math.max(1, ...draft.picks.map((pick) => exactPicks ? pick.pick : pick.round));
  const rows = [...players.values()].map((record) => {
    const pick = picks.get(record.key);
    const position = positionFor(record.player);
    return { ...record.player, key: record.key, position: position.label, color: position.color, isKeeper: record.isKeeper || pick?.keeper === true,
      draft: pick ?? null, undrafted: !pick && (draft.complete || explicitlyUndrafted.has(record.key)),
      draftUnknown: !pick && !draft.complete && !explicitlyUndrafted.has(record.key),
      x: pick ? exactPicks ? pick.pick : pick.round : null,
      points: [...record.weeks.values()].reduce((sum, entry) => sum + entry.points, 0) / 100,
      scoringWeeks: record.weeks.size,
    };
  });
  const rounds = Math.max(1, ...draft.picks.map((pick) => pick.round));
  return { players: rows, exactPicks, maxDraft, fullPeriodComplete: supplemental?.complete === true,
    rounds, roundTicks: roundTicks(draft.picks, exactPicks, rounds) };
}

export function scatterLayout(rows, maxDraft) {
  const hasUnknown = rows.some((row) => row.draftUnknown);
  const width = hasUnknown ? 1200 : 1060, height = 480;
  const left = 70, right = hasUnknown ? 1150 : 1010, top = 28, bottom = 405;
  const unknownX = 1088;
  const draftRight = 865, undraftedX = 948;
  const low = Math.min(0, ...rows.map((row) => row.points));
  const high = Math.max(1, ...rows.map((row) => row.points));
  const span = high - low;
  const min = low < 0 ? low - span * .06 : 0;
  const max = high + span * .08;
  const y = (points) => bottom - (points - min) / (max - min) * (bottom - top);
  const x = (pick) => left + (pick - 1) / Math.max(1, maxDraft - 1) * (draftRight - left);
  const ordered = [...rows].sort((a, b) => b.points - a.points || a.key.localeCompare(b.key));
  const placed = [];
  for (const row of ordered) {
    const anchor = row.draftUnknown ? unknownX : row.undrafted ? undraftedX : x(row.x);
    // Spread undrafted dots horizontally; drafted dots stay at their true x.
    const candidates = row.undrafted || row.draftUnknown ? [0, -13, 13, -26, 26, -39, 39] : [0];
    const cy = y(row.points);
    let cx = anchor;
    for (const offset of candidates) {
      const candidateX = anchor + offset;
      cx = candidateX;
      if (!placed.some((point) => Math.abs(point.cx - candidateX) < 11 && Math.abs(point.cy - cy) < 11)) break;
    }
    placed.push({ ...row, cx, cy });
  }
  return { width, height, left, right, top, bottom, draftRight, undraftedX, unknownX, hasUnknown, min, max, x, y, points: placed };
}
