import React from 'react';

export default function PlayerRosValue({ player, data }) {
  const source = data.ttc_ros;
  if (!source || Number(source.season) !== Number(data.metadata?.season)) return null;
  const value = source.players?.[player.yahoo_player_key];
  const date = new Date(source.generated_at);
  const updated = Number.isNaN(date.getTime()) ? null : date.toLocaleDateString('en-US', {
    month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC',
  });
  return <section className="player-ros-value" aria-labelledby="player-ros-title">
    <div className="section-heading"><h3 id="player-ros-title">TTC ROS consensus</h3><span className="player-ros-scoring">Half-PPR</span></div>
    {value ? <dl className="player-ros-stats">
      <div><dt>Overall rank</dt><dd>#{value.rank}</dd></div>
      <div><dt>Position rank</dt><dd>{value.position} #{value.position_rank}</dd></div>
      <div><dt>Redraft value</dt><dd>{Number(value.value).toLocaleString('en-US')}</dd></div>
    </dl> : <p className="muted">No matched TTC ranking is available for this player.</p>}
    <p className="muted player-ros-context">Current rest-of-season outlook{updated && <> · <time dateTime={source.generated_at}>{updated}</time></>}{source.cached && ' · Cached feed'}. Values adjusted for half-PPR; 1QB, 12-team baseline.</p>
    <div className="player-ros-links"><a href="https://thetradecalc.com" target="_blank" rel="noopener noreferrer">Values by TheTradeCalc</a>{value && <a href={value.url} target="_blank" rel="noopener noreferrer">Player outlook ↗</a>}</div>
    <details className="player-ros-method"><summary>About this value</summary><p>Consensus-based trade value for non-keeper leagues. It reflects a player’s value for the rest of this season, without accounting for future keeper eligibility or cost. Half-PPR adjustment follows TTC’s position multipliers: RB +1%, WR/TE −1%, other positions unchanged. Ranks are recalculated across the full adjusted player board. This is the current outlook on the date shown, independent of the weeks in the league history.</p></details>
  </section>;
}
