import React, { useMemo, useState } from 'react';
import { PlayerName } from './PlayerHistoryDialog';
import { formatPoints } from './dashboardData';
import { draftProduction } from './draftProductionData';
import { weeklyDraftProduction } from './draftWeeklyProduction';

export default function KeeperPickupCandidates({ data }) {
  const [search, setSearch] = useState('');
  const [position, setPosition] = useState('');
  const [tier, setTier] = useState('');
  const [sort, setSort] = useState('round');
  const exported = data.keeper_pickup_candidates;
  const closed = data.metadata?.keepers_final || exported?.status === 'closed'
    || (exported?.deadline_at && Date.now() >= Date.parse(exported.deadline_at));
  const available = !closed && exported?.status === 'open'
    && Number(exported.season) === Number(data.metadata?.season);
  const candidates = available ? exported.candidates : [];
  const production = useMemo(() => available ? new Map((draftProduction(data, true, true)?.players ?? []).map((p) => [p.key, p.points])) : new Map(), [available, data]);
  const weekly = useMemo(() => available ? new Map((weeklyDraftProduction(data)?.players ?? []).map((p) => [p.key, p])) : new Map(), [available, data]);
  const positions = [...new Set(candidates.flatMap((k) => k.player.positions))].sort();
  const query = search.trim().toLowerCase();
  const filtered = candidates.filter((k) => (!position || k.player.positions.includes(position))
    && (!tier || k.tier === tier)
    && (!query || `${k.player.name} ${k.player.team} ${k.last_team_name}`.toLowerCase().includes(query)))
    .sort((a, b) => (sort === 'points' ? (production.get(b.player.yahoo_player_key) ?? 0) - (production.get(a.player.yahoo_player_key) ?? 0)
      : sort === 'round' ? a.round - b.round : 0) || a.player.name.localeCompare(b.player.name));
  return <section className="panel keeper-pickups" aria-labelledby="keeper-pickups-title">
    <div className="section-heading"><div><p className="eyebrow">Find a keeper before the deadline</p><h2 id="keeper-pickups-title">Keeper pickup candidates</h2></div>
      {(available || closed) && <span className="count-badge">{closed ? 0 : candidates.length} candidates</span>}
    </div>
    {closed ? <p className="muted">Keeper pickup eligibility is closed for this season.</p>
      : !available ? <p className="muted">Pickup candidates aren’t available in this export. Run the updated notebook to include them.</p>
        : <>
          <p className="muted small-note insights-description">Unrostered as of Week {exported.roster_week} · Drafted players previously seen on league rosters. Availability may have changed since that week’s roster check.</p>
          <p className="muted small-note">Undrafted players aren’t listed; their potential keeper cost is round 9. Drafted players must meet the league’s keeper rules. Pickup eligibility closes at the keeper deadline.</p>
          {candidates.length ? <>
            <div className="keeper-filter-grid keeper-pickup-filters">
              <label>Find a pickup candidate<input type="search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Player, NFL team, or last fantasy team" /></label>
              <label>Pickup position<select value={position} onChange={(e) => setPosition(e.target.value)}><option value="">All positions</option>{positions.map((p) => <option key={p}>{p}</option>)}</select></label>
              <label>Pickup tier<select value={tier} onChange={(e) => setTier(e.target.value)}><option value="">All tiers</option>{['gold', 'silver', 'bronze'].map((t) => <option key={t} value={t}>{t}</option>)}</select></label>
              <label>Sort pickup candidates<select value={sort} onChange={(e) => setSort(e.target.value)}><option value="round">Keeper round</option><option value="points">Season points</option><option value="name">Player name</option></select></label>
            </div>
            <p className="muted small-note" role="status">{filtered.length} of {candidates.length} candidates</p>
            <div className="table-scroll"><table className="keeper-pickup-table"><caption className="visually-hidden">Drafted keeper pickup candidates as of Week {exported.roster_week}</caption>
              <thead><tr><th scope="col">Player</th><th scope="col">Potential keeper cost</th><th scope="col">Draft history</th><th scope="col">Last rostered</th><th scope="col">Season points</th><th scope="col">Starter-level weeks</th></tr></thead>
              <tbody>{filtered.map((k) => {
                const key = k.player.yahoo_player_key, weeks = weekly.get(key);
                return <tr key={key}><td><div className="pickup-player">{k.player.headshot_image && <img src={k.player.headshot_image} alt="" loading="lazy" />}<div><PlayerName player={k.player} /><span className="muted">{k.player.positions.join(', ')} · {k.player.team}</span></div></div></td>
                  <td><strong>Round {k.round}</strong><span className={`tier-badge tier-${k.tier}`}>{k.tier}</span></td>
                  <td>{k.draft_status}</td><td>{k.last_team_name}<span className="muted">Week {k.last_rostered_week}</span></td>
                  <td>{production.has(key) ? formatPoints(production.get(key)) : '—'}</td><td>{weeks ? `${weeks.points} / ${weeks.seasonWeeks}` : '—'}</td></tr>;
              })}</tbody></table></div>
            {!filtered.length && <p className="muted">No pickup candidates match these filters.</p>}
            <p className="muted small-note">Season points include available regular-season scores while started, benched, on IR, or unrostered. Starter-level weeks use weekly top 12 QB, 30 RB, 30 WR, and 12 TE finishes.</p>
          </> : <p className="muted">No known drafted keeper candidates were unrostered in Week {exported.roster_week}.</p>}
        </>}
  </section>;
}
