import React from 'react';

export default function ContributionPie({ segments, label, activeKey = null }) {
  const positive = segments.filter((segment) => segment.points > 0);
  const total = positive.reduce((sum, segment) => sum + segment.points, 0);
  let offset = 0;
  return <svg className="contribution-pie" viewBox="0 0 200 200" role="img" aria-label={label}>
    <circle cx="100" cy="100" r="91" fill="var(--border)" />
    {positive.map((segment) => {
      const fraction = segment.points / total;
      const start = offset * Math.PI * 2 - Math.PI / 2;
      offset += fraction;
      const end = offset * Math.PI * 2 - Math.PI / 2;
      const props = { fill: segment.color, opacity: activeKey && activeKey !== segment.key ? .25 : 1 };
      const title = `${segment.name}: ${fraction === 1 ? '100.0' : (fraction * 100).toFixed(1)}%`;
      return fraction >= 1 ? <circle key={segment.key} cx="100" cy="100" r="91" {...props}><title>{title}</title></circle>
        : <path key={segment.key} d={`M100 100 L${100 + Math.cos(start) * 91} ${100 + Math.sin(start) * 91} A91 91 0 ${fraction > .5 ? 1 : 0} 1 ${100 + Math.cos(end) * 91} ${100 + Math.sin(end) * 91} Z`} {...props}><title>{title}</title></path>;
    })}
    {!positive.length && <text x="100" y="104" className="contribution-pie-empty">No positive points</text>}
  </svg>;
}
